def flowFile = session.get()
if (!flowFile) return

def chunkCount = 50
def chunkCountAttr = flowFile.getAttribute('chunk_count')
if (chunkCountAttr) chunkCount = chunkCountAttr.toInteger()

chunkCount.times { i ->
    def clone = session.clone(flowFile)
    clone = session.putAttribute(clone, 'chunk_id', String.valueOf(i))
    clone = session.putAttribute(clone, 'chunk_count', String.valueOf(chunkCount))
    session.transfer(clone, REL_SUCCESS)
}
session.remove(flowFile)
